mapper.select:
SELECT EXISTS (
    SELECT 1 FROM sys_message_delivery delivery
    JOIN sys_message_record record ON record.tenant_id = delivery.tenant_id AND record.record_id = delivery.record_id
    WHERE delivery.tenant_id = #{tenantId} AND delivery.delivery_id != #{deliveryId}
      AND delivery.receiver_key = #{receiverKey} AND delivery.channel_type = #{channelType}
      AND record.template_code = #{templateCode} AND record.biz_id = #{bizId}
      AND delivery.status IN ('PENDING', 'CLAIMED', 'RETRYABLE', 'SENDING', 'UNKNOWN', 'SENT')
      AND delivery.attempt_count > 0 AND record.send_time >= #{cutoff}
)

SELECT delivery_id FROM sys_message_delivery
WHERE tenant_id = #{tenantId} AND (
    (status IN ('PENDING', 'RETRYABLE') AND (next_attempt_time IS NULL OR next_attempt_time <= #{now}))
    OR (status IN ('CLAIMED', 'SENDING') AND claim_until <= #{now})
) ORDER BY delivery_id LIMIT #{limit}
